public interface Service {
    void execute();
}

public class ServiceImpl implements Service {
    @Override
    public void execute() { System.out.println("Executing business logic"); }
}

// JDK Dynamic Proxy Usage
Service target = new ServiceImpl();
Service jdkProxy = (Service) Proxy.newProxyInstance(
    Service.class.getClassLoader(),
    new Class<?>[]{Service.class},
    (proxy, method, args) -> {
        System.out.println("Before JDK proxy call");
        Object result = method.invoke(target, args);
        System.out.println("After JDK proxy call");
        return result;
    }
);
jdkProxy.execute();
